import Foundation
import CryptoKit

/// streetzim-recipe/2: no ZIM rewriting is performed on the device.
/// Only verified source ranges and generated bytes are copied, in order.
struct StreetZimRecipe: Decodable, Sendable {
    let format: String
    let uuid: String
    let name: String
    let fileName: String?
    let size: Int64
    let md5: String
    let fileMD5: String?
    let base: Source
    let packs: [String: Source]
    let segments: [Segment]

    enum CodingKeys: String, CodingKey {
        case format, uuid, name, size, md5, base, packs, segments
        case fileName = "file_name"
        case fileMD5 = "file_md5"
    }

    struct Source: Decodable, Sendable {
        let file: String
        let size: Int64
        let uuid: String
        let chunk: Int64
        let sha256: [String]
        let mask: [[Int64]]?
        let url: String?

        @discardableResult
        func validate() throws -> MaskIndex {
            try Task.checkCancellation()
            guard size > 0, chunk > 0, chunk <= 16 * 1024 * 1024,
                  sha256.count == (size - 1) / chunk + 1,
                  UUID(uuidString: normalizedUUID) != nil else { throw StreetZimError.invalidRecipe }
            for hash in sha256 {
                try Task.checkCancellation()
                guard StreetZimRecipe.isHex(hash, count: 64) else { throw StreetZimError.invalidRecipe }
            }
            return try MaskIndex(mask ?? [], size: size)
        }

        var normalizedUUID: String {
            let hex = uuid.replacingOccurrences(of: "-", with: "")
            guard hex.count == 32 else { return "" }
            let chars = Array(hex)
            return [chars[0..<8], chars[8..<12], chars[12..<16], chars[16..<20], chars[20..<32]]
                .map { String($0) }.joined(separator: "-")
        }

    }

    struct Segment: Decodable, Sendable {
        let src: String
        let pack: String?
        let off: Int64?
        let len: Int64?
        let data: String?
        let sha256: String?
    }

    /// A union of nonempty, ordered, disjoint half-open ranges. Duplicate,
    /// overlapping and adjacent masks have exactly the same zeroing semantics.
    struct MaskIndex: Sendable {
        let ranges: [Range<Int64>]

        init(_ masks: [[Int64]], size: Int64) throws {
            var ordered: [Range<Int64>] = []
            ordered.reserveCapacity(masks.count)
            for mask in masks {
                try Task.checkCancellation()
                guard mask.count == 2, mask[0] >= 0, mask[1] >= 0,
                      mask[0] <= size, mask[1] <= size - mask[0] else {
                    throw StreetZimError.invalidRecipe
                }
                if mask[1] > 0 { ordered.append(mask[0]..<mask[0] + mask[1]) }
            }
            var comparisons = 0
            try ordered.sort {
                comparisons += 1
                if comparisons % 1024 == 0 { try Task.checkCancellation() }
                return $0.lowerBound < $1.lowerBound
            }
            var merged: [Range<Int64>] = []
            for range in ordered {
                try Task.checkCancellation()
                if let last = merged.last, range.lowerBound <= last.upperBound {
                    merged[merged.count - 1] = last.lowerBound..<max(last.upperBound, range.upperBound)
                } else {
                    merged.append(range)
                }
            }
            ranges = merged
        }

        private func firstRange(endingAfter offset: Int64) -> Int {
            var lower = 0
            var upper = ranges.count
            while lower < upper {
                let middle = lower + (upper - lower) / 2
                if ranges[middle].upperBound <= offset { lower = middle + 1 } else { upper = middle }
            }
            return lower
        }

        func overlaps(_ range: Range<Int64>) -> Bool {
            guard !range.isEmpty else { return false }
            let index = firstRange(endingAfter: range.lowerBound)
            return index < ranges.count && ranges[index].lowerBound < range.upperBound
        }

        func masked(_ data: Data, at offset: Int64) throws -> Data {
            var result = data
            let end = offset + Int64(data.count)
            var index = firstRange(endingAfter: offset)
            while index < ranges.count, ranges[index].lowerBound < end {
                try Task.checkCancellation()
                let range = ranges[index]
                let lower = Int(max(range.lowerBound, offset) - offset)
                let upper = Int(min(range.upperBound, end) - offset)
                result.resetBytes(in: lower..<upper)
                index += 1
            }
            return result
        }
    }

    var outputName: String { (fileName ?? name) + ".zim" }

    @discardableResult
    func validate() throws -> [String: MaskIndex] {
        try Task.checkCancellation()
        guard format == "streetzim-recipe/2", UUID(uuidString: uuid) != nil,
              Self.isHex(md5, count: 32), fileMD5.map({ Self.isHex($0, count: 32) }) ?? true,
              size > 16, !segments.isEmpty, segments.last?.src == "md5",
              !outputName.contains("/"), !outputName.contains("\\"),
              !outputName.hasPrefix("."), outputName.utf8.count <= 240 else {
            throw StreetZimError.invalidRecipe
        }
        var masks = ["base": try base.validate()]
        for (key, source) in packs {
            try Task.checkCancellation()
            masks["pack:" + key] = try source.validate()
        }
        var total: Int64 = 0
        for (index, segment) in segments.enumerated() {
            try Task.checkCancellation()
            let length: Int64
            switch segment.src {
            case "md5":
                guard index == segments.count - 1 else { throw StreetZimError.invalidRecipe }
                length = 16
            case "inline":
                guard let encoded = segment.data, let bytes = Data(base64Encoded: encoded),
                      let len = segment.len, Int64(bytes.count) == len,
                      let expected = segment.sha256, Self.sha256(bytes) == expected else {
                    throw StreetZimError.integrity
                }
                length = len
            case "base", "pack":
                let source = segment.src == "base" ? base : packs[segment.pack ?? ""]
                guard let source, let off = segment.off, let len = segment.len,
                      off >= 0, len >= 0, off <= source.size, len <= source.size - off,
                      let mask = masks[segment.src == "base" ? "base" : "pack:" + (segment.pack ?? "")],
                      !mask.overlaps(off..<off + len) else {
                    throw StreetZimError.invalidRecipe
                }
                length = len
            default: throw StreetZimError.invalidRecipe
            }
            guard length <= size - total else { throw StreetZimError.invalidRecipe }
            total += length
        }
        guard total == size else { throw StreetZimError.invalidRecipe }
        return masks
    }

    func validateInBackground() async throws {
        try await Self.runValidation { _ = try validate() }
    }

    /// Keep CPU-bound validation off the caller's actor while retaining the
    /// caller's task and cooperative cancellation, without detached task ownership.
    @concurrent
    static func runValidation(_ operation: @Sendable () throws -> Void) async throws {
        try Task.checkCancellation()
        try operation()
        try Task.checkCancellation()
    }

    static func sha256(_ bytes: Data) -> String { hex(SHA256.hash(data: bytes)) }
    static func hex<S: Sequence>(_ bytes: S) -> String where S.Element == UInt8 {
        bytes.map { String(format: "%02x", $0) }.joined()
    }
    static func isHex(_ string: String, count: Int) -> Bool {
        string.utf8.count == count && string.utf8.allSatisfy { (48...57).contains($0) || (97...102).contains($0) }
    }
}
